EXPEDIENTE = "SELECT 'Datos sinteticos; plan de demostracion no oficial' AS fuente,\nupper(trim(%(codigo)s::text)) AS codigo_solicitado,\n(SELECT (to_jsonb(r)-'codigo')||jsonb_build_object('codigo',upper(trim(%(codigo)s::text))) || jsonb_build_object('porcentaje_avance',round(100.0*r.creditos_aprobados/nullif(r.creditos_plan,0),2),'minimo_semestres_por_creditos',ceil((r.creditos_plan-r.creditos_aprobados)/18.0)) FROM academico_demo.v_resumen r WHERE r.codigo=(SELECT codigo FROM academico_demo.estudiantes WHERE codigo_institucional=upper(trim(%(codigo)s::text)))) AS resumen,\nCASE WHEN %(detalle)s::text IN ('historial','completo') THEN coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.semestre,t.materia,t.periodo) FROM\n(SELECT h.periodo,h.materia,m.nombre,m.semestre,m.creditos,h.nota,h.estado FROM academico_demo.historial h JOIN academico_demo.materias m ON m.codigo=h.materia WHERE h.estudiante=(SELECT codigo FROM academico_demo.estudiantes WHERE codigo_institucional=upper(trim(%(codigo)s::text)))) t),'[]'::jsonb) ELSE '[]'::jsonb END AS historial,\nCASE WHEN %(detalle)s::text IN ('pendientes','completo') THEN coalesce((SELECT jsonb_agg(to_jsonb(p)-'estudiante' ORDER BY p.semestre,p.materia) FROM academico_demo.v_materias_pendientes p WHERE p.estudiante=(SELECT codigo FROM academico_demo.estudiantes WHERE codigo_institucional=upper(trim(%(codigo)s::text)))),'[]'::jsonb) ELSE '[]'::jsonb END AS pendientes;"

PLAN = "SELECT 'Plan simplificado ficticio de Ingenieria de Sistemas; no oficial' AS fuente,\n3.0 AS nota_minima_aprobatoria_demo,18 AS limite_creditos_por_semestre_demo,\n(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.semestre,t.codigo) FROM\n(SELECT m.*,ARRAY(SELECT p.requisito FROM academico_demo.prerrequisitos p WHERE p.materia=m.codigo ORDER BY p.requisito) AS prerrequisitos FROM academico_demo.materias m) t) AS plan,\n(SELECT jsonb_agg(jsonb_build_object('codigo',codigo_institucional,'nombre',nombre) ORDER BY codigo) FROM academico_demo.estudiantes) AS estudiantes_demo;"

PROYECCION = "SELECT (SELECT (to_jsonb(r)-'codigo')||jsonb_build_object('codigo',upper(trim(%(codigo)s::text))) FROM academico_demo.v_resumen r WHERE r.codigo=(SELECT codigo FROM academico_demo.estudiantes WHERE codigo_institucional=upper(trim(%(codigo)s::text)))) AS resumen, academico_demo.proyectar_semestres((SELECT codigo FROM academico_demo.estudiantes WHERE codigo_institucional=upper(trim(%(codigo)s::text))),18) || jsonb_build_object('codigo',upper(trim(%(codigo)s::text))) AS proyeccion;"

NOTICIAS = "SELECT 'Publicaciones oficiales en la categoria Ingenieria de Sistemas de la UNAB' AS fuente,\n(SELECT ultima_actualizacion_ok FROM academico_demo.estado_fuentes WHERE fuente='noticias_sistemas_unab') AS ultima_actualizacion_exitosa,\ncoalesce((SELECT now()-ultima_actualizacion_ok>interval '48 hours' FROM academico_demo.estado_fuentes WHERE fuente='noticias_sistemas_unab'),true) AS cache_desactualizada,\n(SELECT count(*) FROM academico_demo.noticias) AS total_guardadas,\ncoalesce((SELECT jsonb_agg(to_jsonb(n) ORDER BY n.publicada_en DESC) FROM\n (SELECT titulo,resumen,url,publicada_en,consultada_en FROM academico_demo.noticias WHERE publicada_en<=now() ORDER BY publicada_en DESC LIMIT 6) n),'[]'::jsonb) AS noticias;"
